import { atom, selector } from "recoil";
import IToDo from "./interfaces/IToDo";

export const toDoListState = atom<IToDo[]>({
	key: "toDo",
	default: [],
});

export const toDoSelector = selector({
	key: "toDoSelector",
	get: ({ get }) => {
		return "something happen"
	},
});
